from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class AuthMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.auth.api_permissions")
    def api_permissions(self):
        """
        Получение списка прав пользователя
        """
        return self.get(path="api/permissions")

    @tracer.start_as_current_span("admin.auth.auth_otp_generate")
    def auth_otp_generate(self, email: str):
        """
        Ручка для определения возможности создания токена
        для передданного email,
        в случае успеха запускает механизм сздания токена
        """
        return self.post(path="auth/otp/generate", json={"email": email})

    @tracer.start_as_current_span("admin.auth.auth_otp_check")
    def auth_otp_check(self, email: str, password: str):
        """
        Ручка для проверки активной OTP-авторизации
        """
        return self.post(path="auth/otp/check", json={"email": email, "password": password})

    @tracer.start_as_current_span("admin.auth.auth_logout")
    def auth_logout(self):
        """
        Выход из аккаунта
        """
        return self.get(path="auth/logout")

    @tracer.start_as_current_span("admin.auth.auth_check")
    def auth_check(self):
        """
        Проверка существования сессии
        """
        return self.get(path="auth/check")
